class Heap {
  items: number[] = [];
  before: (a: number, b: number) => boolean;
  constructor(before: (a: number, b: number) => boolean) {
    this.before = before;
  }
  get size(): number { return this.items.length; }
  peek(): number { return this.items[0]; }
  push(x: number): void {
    const h = this.items;
    h.push(x);
    let i = h.length - 1;
    while (i > 0 && this.before(h[i], h[(i - 1) >> 1])) {
      [h[i], h[(i - 1) >> 1]] = [h[(i - 1) >> 1], h[i]];
      i = (i - 1) >> 1;
    }
  }
  pop(): number {
    const h = this.items;
    const top = h[0];
    const last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && this.before(h[l], h[m])) m = l;
        if (r < h.length && this.before(h[r], h[m])) m = r;
        if (m === i) break;
        [h[i], h[m]] = [h[m], h[i]];
        i = m;
      }
    }
    return top;
  }
}

class MedianTracker {
  low = new Heap((a, b) => a > b);  // max-heap: the smaller half
  high = new Heap((a, b) => a < b); // min-heap: the larger half
  add(ms: number): void {
    if (this.low.size === 0 || ms <= this.low.peek()) this.low.push(ms);
    else this.high.push(ms);
    if (this.low.size > this.high.size + 1) this.high.push(this.low.pop());
    else if (this.high.size > this.low.size) this.low.push(this.high.pop());
  }
  median(): number {
    if (this.low.size === 0) throw new Error("no samples yet");
    if (this.low.size > this.high.size) return this.low.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}

// Test adapter: feed samples one at a time, collect the median after each.
function medians(samples: number[]): number[] {
  const tracker = new MedianTracker();
  const out: number[] = [];
  for (const ms of samples) {
    tracker.add(ms);
    out.push(tracker.median());
  }
  return out;
}
